{
  "headline": "FDA's records trace our supply to a plant classified OAI 809 days before the posting",
  "headline_cites": ["D6"],
  "sentences": [
    {
      "text": "FDA first posted the sterile water injection shortage on 2021-11-23 and it remains current as of 2026-10-21.",
      "cites": ["E70", "D29"]
    },
    {
      "text": "An FDA inspection at Pfizer Healthcare India Private Limited (FEI 3008316085) ended 2019-09-06 and was classified OAI, 809 days before the shortage posting.",
      "cites": ["D6"]
    },
    {
      "text": "A Warning Letter was issued to the same plant on 2020-03-25, 608 days before the posting.",
      "cites": ["D9"]
    },
    {
      "text": "Nephron SC, LLC (FEI 3010892830) received a Warning Letter on 2020-09-22, 427 days before the posting, and later an OAI inspection ending 2022-04-20, 148 days after the posting.",
      "cites": ["D10", "D11"]
    },
    {
      "text": "Hospira, Inc. (FEI 1021343) had a VAI inspection ending 2019-11-21, 733 days before the posting.",
      "cites": ["D8"]
    },
    {
      "text": "The rule-based best option is to buy from American Regent, Inc., which is not on FDA's shortage list today and whose plant last received a VAI inspection on 2024-04-24.",
      "cites": ["D30"]
    }
  ]
}
